package sample.bidi;
/** JIRPrescanFixtures uses normal()'s location, not its body or analysis root. */
public final class BidiPrescanSample {
    public static Object normal(Object value) { return value; }
}

package sample.bidi;
/** BidiJIRTestUtils uses only copy()'s location to select known project bytecode. */
public final class BidiStatementSample {
    public Object copy(Object value) { return value; }
}

package sample.bidi;

/** Real bytecode, fields, getters, calls and javac try/finally lowering.
 * Source/sink metadata is supplied by the diagnostic, not by summaries.
 */
public final class LockWorkflowSample {
    public static final class WorkflowTask {
        private final String expression;
        public WorkflowTask(String expression) { this.expression = expression; }
        public String getExpression() { return expression; }
    }
    public static final class WorkflowDef {
        private final WorkflowTask[] tasks;
        public WorkflowDef(WorkflowTask[] tasks) { this.tasks = tasks; }
        public WorkflowTask[] getTasks() { return tasks; }
    }
    public static final class WorkflowModel {
        private final WorkflowDef workflowDefinition;
        private final String workflowId;
        public WorkflowModel(WorkflowDef definition, String workflowId) {
            this.workflowDefinition = definition;
            this.workflowId = workflowId;
        }
        public WorkflowDef getWorkflowDefinition() { return workflowDefinition; }
        public String getWorkflowId() { return workflowId; }
    }
    public static final class Lock {
        public boolean acquireLock(String id) { return true; }
        public void releaseLock(String id) { }
    }
    public static final class Operations {
        private final Lock lock = new Lock();
        public void createAndEvaluate(WorkflowModel workflow) {
            if (!lock.acquireLock(workflow.getWorkflowId())) {
                throw new IllegalStateException("lock rejected");
            }
            try {
                createAndEvaluateWithLock(workflow);
            } finally {
                lock.releaseLock(workflow.getWorkflowId());
            }
        }
        private void createAndEvaluateWithLock(WorkflowModel workflow) {
            evaluateDefinition(workflow.getWorkflowDefinition());
        }
    }
    public static void sink(String expression) { }
    private static void evaluateDefinition(WorkflowDef definition) {
        WorkflowTask task = definition.getTasks()[0];
        sink(task.getExpression());
    }
    public static void direct(WorkflowModel workflow) {
        evaluateDefinition(workflow.getWorkflowDefinition());
    }
    public static void locked(WorkflowModel workflow) {
        new Operations().createAndEvaluate(workflow);
    }
}

