data class MethodWithContext(val method: CommonMethod, val ctx: MethodContext)

data class MethodEntryPoint(val context: MethodContext, val statement: CommonInst) {
    val method: CommonMethod get() = statement.location.method

    override fun toString(): String = "$method [$context]"
}

abstract class AbstractJIRInst(override val location: JIRInstLocation) : JIRInst {
    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as AbstractJIRInst

        if (location != other.location) return false

        return true
    }

    override fun hashCode(): Int {
        return location.hashCode()
    }
}

data class JIRInstRef(
    val index: Int,
)

class JIRInstLocationImpl(
        override val method: JIRMethod,
        override val index: Int,
        override val lineNumber: Int
) : JIRInstLocation {

    override fun toString(): String {
        return "${method.enclosingClass.name}#${method.name}:$lineNumber"
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (javaClass != other?.javaClass) return false

        other as JIRInstLocationImpl

        if (index != other.index) return false
        return method == other.method
    }

    override fun hashCode(): Int {
        var result = index
        result = 31 * result + method.hashCode()
        return result
    }

sealed interface JMethodBoundaryInst : JIRBranchingInst

class JMethodEnterInst(location: JIRInstLocation) : AbstractJIRInst(location), JMethodBoundaryInst {
    override val operands: List<JIRExpr> get() = emptyList()
    override val successors: List<JIRInstRef> get() = emptyList()

    override fun toString(): String = "method enter"

    override fun <T> accept(visitor: JIRInstVisitor<T>): T = visitor.visitExternalJIRInst(this)
}

class JMethodExitNormalInst(location: JIRInstLocation) : AbstractJIRInst(location), JMethodBoundaryInst {

