package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.MarkMode
import org.opentaint.dataflow.bidi.engine.*
import java.util.Collections

enum class EndReason { STOP_RULE, NO_DEMAND_EDGE, POLICY, ABNORMAL }

data class AnalysisEnd(
    val status: RunStatus, val run: Int, val direction: Direction, val reason: EndReason,
    val run1MarkMode: MarkMode = MarkMode.FULL,
)

/** Only settled configured-root ZERO terminal identities enter the report. */
class Report(entries: List<Entry>, val end: AnalysisEnd) {
    val entries: List<Entry> = Collections.unmodifiableList(ArrayList(entries))
    data class Entry(val id: ReportId, val descriptor: ReportDescriptor)
}

/** One completed driver barrier commits retained relations and root reports together. */
class ReportBuilder {
    class Snapshot internal constructor(val normal: NormalTargetView, entries: Map<ReportId, Report.Entry>) {
        internal val entries = Collections.unmodifiableMap(LinkedHashMap(entries))
    }
    private var state = Snapshot(NormalTargetView.EMPTY, emptyMap())
    val normalTargets: NormalTargetView get() = state.normal
    val reportCount: Int get() = state.entries.size

    fun prepare(config: RunConfig, result: RunResult<RunMethodAnalyzer>, shared: SharedObjects): Snapshot {
        check(result.status == RunStatus.COMPLETE)
        if (config.direction != Direction.FORWARD) return state
        val entries = LinkedHashMap(state.entries)
        for (actor in result.analyzers) {
            shared.cancellation.checkpoint()
            if (actor.key !in config.roots) continue
            for (row in actor.targets) {
                val target = row.target as? Target.NormalTarget ?: continue
                if (row.premise.isZero) entries.putIfAbsent(target.id,
                    Report.Entry(target.id, shared.reportCatalog.descriptor(target.id)))
            }
        }
        val fresh = result.analyzers.asSequence().flatMap { actor ->
            actor.targets.asSequence().mapNotNull { row ->
                (row.target as? Target.NormalTarget)?.let { OwnedNormalTarget(actor.key, row.premise, it.id) }
            }
        }
        val local = result.analyzers.asSequence().flatMap { it.blockTargets() }.flatMap { block ->
            block.rows.asSequence().mapNotNull { row ->
                (row.target as? Target.NormalTarget)?.let {
                    OwnedNormalTarget(block.method, row.premise, it.id, block.scope)
                }
            }
        }
        val normal = NormalTargetStore(shared.ap, state.normal.rows() + fresh + local)
        check(normal.zeroRows().all { it.id in entries }) {
            "Every retained ZERO terminal must reach a configured root before the barrier"
        }
        return Snapshot(normal, entries)
    }

    fun commit(prepared: Snapshot) { state = prepared }
    fun build(end: AnalysisEnd): Report = Report(state.entries.values.toList(), end)
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.OwnedScope
import java.util.Collections

/** A run reads a fixed view. Only a complete driver barrier builds its successor. */
interface NormalTargetView {
    fun contains(method: MethodKey, premise: PremiseKey, id: ReportId): Boolean
    fun candidates(method: MethodKey, part: Subscription, mode: ApMode): List<Pair<TargetSummary, Int>>
    fun contains(method: MethodKey, scope: BlockScope?, premise: PremiseKey, id: ReportId): Boolean =
        scope == null && contains(method, premise, id)
    fun candidates(method: MethodKey, scope: BlockScope?, original: PremiseKey, actual: Facts,
                   mode: ApMode): List<Pair<TargetSummary, Int>> = emptyList()
    /** Complete snapshot, including internal scopes for future local replay. */
    fun rows(): Sequence<OwnedNormalTarget>
    /** Only public method ZERO rows participate in root report accounting. */
    fun zeroRows(): Sequence<OwnedNormalTarget> = rows().filter { it.scope == null && it.premise.isZero }

    companion object {
        val EMPTY = object : NormalTargetView {
            override fun contains(method: MethodKey, premise: PremiseKey, id: ReportId) = false
            override fun candidates(method: MethodKey, part: Subscription, mode: ApMode) = emptyList<Pair<TargetSummary, Int>>()
            override fun rows() = emptySequence<OwnedNormalTarget>()
        }
    }
}

/** Shares the existing premise index. Target identities do not change AP equality. */
class NormalTargetStore(ap: ApManager, records: Sequence<OwnedNormalTarget>) : NormalTargetView {
    private val members: Set<OwnedNormalTarget>
    private val byMethod: Map<MethodKey, PublicationIndex>
    private val byScope: Map<OwnedScope, PublicationIndex>

    init {
        val owned = LinkedHashSet<OwnedNormalTarget>()
        val indexes = LinkedHashMap<MethodKey, PublicationIndex>()
        val scoped = LinkedHashMap<OwnedScope, PublicationIndex>()
        for (record in records) {
            ap.cancellation.checkpoint()
            if (!RuntimeDataDomain.premise(record.premise) || !owned.add(record)) continue
            val index = if (record.scope == null) indexes.getOrPut(record.method) { PublicationIndex(ap, ApOps(ap)) }
                else scoped.getOrPut(OwnedScope(record.method, record.scope)) { PublicationIndex(ap, ApOps(ap)) }
            index.addTargets(listOf(TargetSummary(record.premise, Target.NormalTarget(record.id))))
        }
        members = Collections.unmodifiableSet(owned)
        byMethod = Collections.unmodifiableMap(indexes)
        byScope = Collections.unmodifiableMap(scoped)
    }

    override fun contains(method: MethodKey, premise: PremiseKey, id: ReportId): Boolean =
        OwnedNormalTarget(method, premise, id) in members
    override fun candidates(method: MethodKey, part: Subscription, mode: ApMode): List<Pair<TargetSummary, Int>> =
        byMethod[method]?.targetCandidates(part, mode).orEmpty()
    override fun contains(method: MethodKey, scope: BlockScope?, premise: PremiseKey, id: ReportId): Boolean =
        OwnedNormalTarget(method, premise, id, scope) in members
    override fun candidates(method: MethodKey, scope: BlockScope?, original: PremiseKey, actual: Facts,
                            mode: ApMode): List<Pair<TargetSummary, Int>> =
        (if (scope == null) byMethod[method] else byScope[OwnedScope(method, scope)])
            ?.targetCandidates(original, actual, mode).orEmpty()
    override fun rows(): Sequence<OwnedNormalTarget> = members.asSequence()
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.MethodKey
import org.opentaint.dataflow.bidi.ap.PremiseKey
import org.opentaint.dataflow.bidi.store.BlockScope

@JvmInline value class ReportId(val value: Int)

/** Terminal observations have no AP geometry and never become method facts. */
sealed interface Target {
    data class NormalTarget(val id: ReportId) : Target
    data object DemandTarget : Target
}

data class TargetSummary(val premise: PremiseKey, val target: Target)
data class OwnedNormalTarget(val method: MethodKey, val premise: PremiseKey, val id: ReportId,
                             val scope: BlockScope? = null)
typealias TargetBatch = List<TargetSummary>

/** The existing static continuation can carry an AP image or a terminal result. */
sealed interface StaticCallResult {
    data class Ap(val publication: Publication) : StaticCallResult
    data class Terminal(val summary: TargetSummary) : StaticCallResult
    val premise: PremiseKey get() = when (this) {
        is Ap -> publication.premise
        is Terminal -> summary.premise
    }
}

fun interface TargetPublicationSink {
    fun publishTargets(method: MethodKey, batch: TargetBatch)
}

interface TargetApplier {
    fun applyTarget(part: Subscription, row: TargetSummary, member: Int) {
        error("This summary applier does not support terminal results")
    }
    fun applyStaticTarget(part: Subscription, row: TargetSummary, member: Int) {
        error("This summary applier does not support static terminal results")
    }
}

