            if(type.endsWith("$ControlZero"))row.put("kind","CONTROL_ZERO");
            else if(type.endsWith("$Group")){int group=integer(get(atom,"id"));row.put("kind","GROUP");row.put("group",group);row.put("groupKey",simple(listAt(obj(obj(table,"groups"),"keys"),group),"encoded"));}
            else if(type.endsWith("$Full")){ObjectReference exact=obj(atom,"mark");int group=integer(get(exact,"group")),full=integer(get(exact,"full"));row.put("kind","FULL");row.put("group",group);row.put("full",full);row.put("groupKey",simple(listAt(obj(obj(table,"groups"),"keys"),group),"encoded"));row.put("fullKey",simple(listAt(obj(obj(table,"fulls"),"keys"),full),"group","name"));}
            else throw new Incomplete("UNKNOWN_MARK_ATOM "+type);markRows.add(row);
        }
        return map("managerObjectId",uid(manager),"fields",fieldRows,"marks",markRows,"resolution","Field reads of published AccessorTable/MarkTable arrays; no catalog methods called.");
    }
    static Map<String,Object> scope(ObjectReference value){return simple(value,"block","entry");}
    static Map<String,Object> context(ObjectReference value,int depth){
        if(value==null)return null;if(depth>8)throw new Oversized("CONTEXT_DEPTH");String type=value.referenceType().name();Map<String,Object> result=map("type",type,"objectId",uid(value));
        if(type.endsWith("EmptyMethodContext"))return result;
        if(type.endsWith("CombinedMethodContext")){result.put("first",context(obj(value,"first"),depth+1));result.put("second",context(obj(value,"second"),depth+1));return result;}
        if(type.endsWith("JIRArgumentTypeMethodContext")||type.endsWith("JIRInstanceTypeMethodContext")){
            if(type.endsWith("JIRArgumentTypeMethodContext"))result.put("argIdx",integer(get(value,"argIdx")));ObjectReference constraint=obj(value,"typeConstraint");result.put("exactType",primitive(get(constraint,"exactType")));result.put("class",classInfo(obj(constraint,"type")));return result;
        }
        result.put("unknownContext",true);return result;
    }
    /** Native and virtual methods store the same descriptor under different fields.
     * JIREnrichedVirtualMethod and JIRLambdaMethod inherit name/description from
     * JIRVirtualMethodImpl; no method is skipped because its implementation is virtual. */
    static Map<String,Object> methodInfo(ObjectReference value){
        Field info=findField(value,"methodInfo");
        if(info!=null){ObjectReference nativeInfo=object(value.getValue(info));if(nativeInfo==null)throw new Incomplete("NULL_METHOD_INFO "+value.referenceType().name());Map<String,Object> row=simple(nativeInfo,"name","desc");row.put("storage","NATIVE_METHOD_INFO");return row;}
        Field name=findField(value,"name"),description=findField(value,"description");
        if(name!=null&&description!=null)return map("type",value.referenceType().name(),"objectId",uid(value),"name",string(value.getValue(name)),"desc",string(value.getValue(description)),"storage","VIRTUAL_STORED_NAME_DESCRIPTION");
        throw new Incomplete("METHOD_METADATA_FIELDS_UNAVAILABLE "+value.referenceType().name());
    }
    static Map<String,Object> classInfo(ObjectReference value){
        Map<String,Object> result=map("type",value.referenceType().name(),"objectId",uid(value));Field source=findField(value,"classSource");if(source!=null&&value.getValue(source)!=null){result.put("name",string(get(object(value.getValue(source)),"className")));return result;}Field info=findField(value,"cachedInfo");
        if(info!=null&&value.getValue(info)!=null)result.put("name",string(get(object(value.getValue(info)),"name")));
        else{Field name=findField(value,"name");if(name!=null){result.put("name",string(value.getValue(name)));result.put("nameStorage","VIRTUAL_STORED_NAME");}else result.put("nameUnavailableWithoutGetter",true);}return result;
    }
    static Map<String,Object> owner(ObjectReference value){
        ObjectReference entry=obj(value,"method"),statement=obj(entry,"statement"),location=obj(statement,"location"),method=obj(location,"method");
        Map<String,Object> result=map("objectId",uid(value),"scope",scope(obj(value,"local")),"methodEntryObjectId",uid(entry),"entryStatementType",statement.referenceType().name(),"entryIndex",primitive(get(location,"index")),"entrySourceLine",primitive(get(location,"lineNumber")),"context",context(obj(entry,"context"),0),"declaringClass",classInfo(obj(method,"enclosingClass")));
        result.put("method",methodInfo(method));return result;
    }
    static Map<String,Object> input(ObjectReference value){
        ObjectReference key=obj(value,"key");Map<String,Object> result=map("objectId",uid(value),"parent",owner(obj(value,"parent")),"zeroOnly",primitive(get(value,"zeroOnly")),"keyType",key.referenceType().name(),"keyObjectId",uid(key));
        if(key.referenceType().name().endsWith("$Local")){ObjectReference link=obj(key,"link");result.put("link",map("objectId",uid(link),"parent",scope(obj(link,"parent")),"child",scope(obj(link,"child")),"point",primitive(get(link,"point")),"layer",enumName(get(link,"layer"))));}
        else{ObjectReference ref=obj(key,"ref");result.put("callRef",map("objectId",uid(ref),"stageOrdinal",primitive(get(ref,"stageOrdinal")),"scope",scope(obj(ref,"scope")),"callerLayer",enumName(get(ref,"callerLayer"))));}
        return result;
    }
    static String json(Object value){check();
        if(value==null)return"null";if(value instanceof Number||value instanceof Boolean)return value.toString();
        if(value instanceof String){StringBuilder out=new StringBuilder("\"");for(char c:((String)value).toCharArray()){if(c=='"'||c=='\\')out.append('\\').append(c);else if(c=='\n')out.append("\\n");else if(c=='\r')out.append("\\r");else if(c=='\t')out.append("\\t");else if(c<32)out.append(String.format("\\u%04x",(int)c));else out.append(c);}return out.append('"').toString();}
        if(value instanceof Map){List<String> parts=new ArrayList<>();for(var e:((Map<?,?>)value).entrySet())parts.add(json(e.getKey().toString())+":"+json(e.getValue()));return"{"+String.join(",",parts)+"}";}
        if(value instanceof Iterable){List<String> parts=new ArrayList<>();for(Object e:(Iterable<?>)value)parts.add(json(e));return"["+String.join(",",parts)+"]";}throw new IllegalArgumentException("JSON_TYPE "+value.getClass());
    }
}

